        ("-g bytes, -groupsize bytes", "Put this many bytes in each group, separated by spaces (default 2; 0 means no spaces).", "-g 1 gives one byte per column, easiest to read."),
        ("-h, -help", "Print a short usage message and exit.", "A quick reminder."),
        ("-i, -include", "Output a C include file: a byte array and its length.", "Embedding shellcode or data in a program."),
