        ("-n name, -name name", "Name the array used by -i.", "Controlling variable names."),
        ("-o offset", "Add this number to every displayed offset.", "Making the left column match addresses in memory."),
        ("-p, -plain, -ps, -postscript", "Plain continuous hex, with no offsets or text column.", "Copying bytes into a script, or feeding -r."),
        ("-r, -revert", "Reverse the operation: turn a hex dump (or plain hex with -p) back into binary.", "Decoding hex text, patching a file."),
        ("-R when", "Colour the output: always, auto or never.", "Spotting zero bytes and printable text quickly."),
        ("-s [+][-]seek, -seek (for example -s -1)", "Start at this byte offset. A plus sign is relative to the current position when reading standard input; a minus sign counts from the end of the file, for example -s -1 or -s -40.", "Looking at a trailer, or jumping to an offset found with grep -b or strings -t."),
        ("-u", "Use upper-case hexadecimal digits.", "Matching a document or tool that expects capitals."),
        ("-v, -version", "Print the version and exit.", "Checking which xxd you have."),
