    try_=["Dump pic.png and find the IEND chunk and the data after it.", "Convert the string flag{ok} to hex and back with xxd.", "Dump hello with -g 1 and find the text of the secret string.", "Use grep -b to find a text offset, then xxd -s to view the bytes around it."],
